insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 71, 24, 'Minha língua também falará de tua justiça o dia todo, pois já estão envergonhados e humilhados aqueles que procuram me [fazer] mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 1, 'Para Salomão Deus, dá teus juízos ao rei, e tua justiça ao filho do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 2, 'Ele julgará a teu povo com justiça, e a teus aflitos com juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 3, 'Os montes trarão paz ao povo, e os morros [trarão] justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 4, 'Ele julgará os pobres do povo, livrará os filhos do necessitado, e quebrará o opressor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 5, 'Temerão a ti enquanto durarem o sol e a luz, geração após geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 6, 'Ele descerá como chuva sobre a [erva] cortada, como as chuvas que regam a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 7, 'Em seus dias o justo florescerá, e [haverá] abundância de paz, até que não [haja] mais a lua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 8, 'E ele terá domínio de mar a mar; e desde o rio até os limites da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 9, 'Os moradores dos desertos se inclinarão perante sua presença, e seus inimigos lamberão o pó da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 10, 'Os reis de Társis e das ilhas trarão presentes; os reis de Sabá e Seba apresentarão bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 11, 'E todos os reis se inclinarão a ele; todas as nações o servirão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 12, 'Porque ele livrará ao necessitado que clamar, e também ao aflito que não tem quem o ajude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 13, 'Ele será piedoso para o pobre e necessitado, e salvará as almas dos necessitados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 14, 'Ele livrará suas almas da falsidade e da violência, e o sangue deles lhe será precioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 15, 'E ele viverá; e lhe darão ouro de Sabá, e continuamente orarão por ele; o dia todo o bendirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 16, 'Haverá bastante trigo na terra sobre os cumes dos montes; seu fruto brotará como o Líbano; e desde a cidade florescerão como a erva da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 17, 'Seu nome permanecerá para sempre; enquanto o sol durar, seu nome continuará; e se bendirão nele; todas as nações o chamarão de bem-aventurado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 18, 'Bendito [seja] o SENHOR Deus, o Deus de Israel! Somente ele faz [tais] maravilhas!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 19, 'E bendito seja seu glorioso nome eternamente; e que sua glória encha toda a terra! Amem, e amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 72, 20, '[Aqui] terminam as orações de Davi, filho de Jessé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 1, 'Salmo de Asafe: Sim, certamente Deus [é] bom para Israel, para os limpos de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 2, 'Eu porém, quase que meus pés se desviaram; quase nada [faltou] para meus passos escorregarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 3, 'Porque eu tinha inveja dos arrogantes, quando via a prosperidade dos perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 4, 'Porque não há problemas para eles até sua morte, e o vigor deles continua firme.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 5, 'Não são tão oprimidos como o homem comum, nem são afligidos como os outros homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 6, 'Por isso eles são rodeados de arrogância como um colar; estão cobertos de violência como [se fosse] um vestido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 7, 'Seus olhos incham de gordura; são excessivos os desejos do coração deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 8, 'Eles são escarnecedores e oprimem falando mal e falando arrogantemente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 9, 'Elevam suas bocas ao céu, e suas línguas andam na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 10, 'Por isso seu povo volta para cá, e as águas lhes são espremidas por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 11, 'E dizem: Como Deus saberia? Será que o Altíssimo tem conhecimento [disto] ?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 12, 'Eis que estes [são] perversos, sempre estão confortáveis e aumentam seus bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 13, '[Cheguei a pensar] : Certamente purifiquei meu coração e lavei minhas mãos na inocência inutilmente,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 14, 'Porque sou afligido o dia todo, e castigado toda manhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 15, 'Se eu tivesse dito [isto] , eu falaria dessa maneira; eis que teria decepcionado a geração de teus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 16, 'Quando tentei entender, isto me pareceu trabalhoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 17, 'Até que entrei nos santuários de Deus, [e] entendi o fim de tais pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 18, 'Certamente tu os fazes escorregarem, [e] os lança em assolações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 19, 'Como eles foram assolados tão repentinamente! Eles se acabaram, [e] se consumiram de medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 20, 'Como o sonho depois de acordar, ó Senhor, quando tu acordares desprezarás a aparência deles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 21, 'Porque meu coração tem se amargurado, e meus rins têm sentido dolorosas picadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 22, 'Então me comportei como tolo, e nada sabia; tornei-me como um animal para contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 23, 'Porém [agora estarei] continuamente contigo; tu tens segurado minha mão direita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 24, 'Tu me guiarás com teu conselho, e depois me receberás [em] glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 25, 'A quem tenho no céu [além de ti] ? E [quando estou] contigo, nada há na terra que eu deseje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 26, 'Minha carne e meu coração desfalecem; [porém] Deus [será] a rocha do meu coração e minha porção para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 27, 'Porque eis que os que ficaram longe de ti perecerão; tu destróis todo infiel a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 73, 28, 'Mas [quanto] a mim, bom me é me aproximar de Deus; ponho minha confiança no Senhor DEUS, para que eu conte todas as tuas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 1, 'Instrução de Asafe: Deus, por que nos rejeitaste para sempre? [Por que] tua ira fumega contra as ovelhas do teu pasto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 2, 'Lembra-te do teu povo, que tu compraste desde a antiguidade; a tribo de tua herança, que resgataste; o monte Sião, em que habitaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 3, 'Percorre as ruínas duradouras, tudo que o inimigo destruiu no santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 4, 'Os teus inimigos rugiram no meio de tuas assembleias; puseram por sinais de vitória os símbolos deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 5, 'Eles eram como o que levantam machados contra os troncos das árvores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 6, 'E agora, com machados e martelos, quebraram todas as obras entalhadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 7, 'Puseram fogo no teu santuário; profanaram [levando] ao chão o lugar onde o teu nome habita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 8, 'Disseram em seus corações: Nós os destruiremos por completo; serão queimadas todas as assembleias de Deus na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 9, 'Já não vemos os nossos sinais; já não há mais profeta; e ninguém entre nós sabe até quando será assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 10, 'Deus, até quando o adversário insultará? O inimigo blasfemará o teu nome para sempre?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 11, 'Por que está afastada a tua mão direita? Tira-a do teu peito!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 12, 'Deus é o meu Rei desde a antiguidade; ele opera salvação no meio da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 13, 'Tu dividiste o mar com a tua força; quebraste as cabeças dos monstros nas águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 14, 'Despedaçaste as cabeças do leviatã; e o deste como alimento ao povo do deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 15, 'Tu dividiste a fonte e o ribeiro; tu secaste os rios perenes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 16, 'A ti pertence o dia, a noite também é tua; tu preparaste a luz e o sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 17, 'Tu estabeleceste todos os limites da terra; tu formaste o verão e o inverno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 18, 'Lembra-te disto: que o inimigo insultou ao SENHOR; e um povo tolo blasfemou o teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 19, 'Não entregues a vida da tua pombinha para os animais selvagens; não te esqueças para sempre da vida dos teus pobres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 20, 'Olha para o [teu] pacto, porque os lugares escuros da terra estão cheios de habitações violentas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 21, 'Não permitas que o oprimido volte humilhado; que o aflito e o necessitado louvem o teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 22, 'Levanta-te, Deus; luta em favor de tua causa; lembra-te do insulto que o tolo faz a ti o dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 74, 23, 'Não te esqueças da voz dos teus adversários; o barulho dos que se levantam contra ti sobe cada vez mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 75, 1, 'Para o regente, conforme “altachete”; salmo e cântico de Asafe: Louvamos a ti, ó Deus; louvamos, e perto [está] o teu nome; são anunciadas as tuas maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 75, 2, 'O que eu recebi, no [tempo] determinado, julgarei de forma justa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 75, 3, 'A terra e todos os seus moradores [são] dissolvidos; [porém] eu fortifiquei suas colunas. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 75, 4, 'Eu disse aos orgulhosos: Não sejais orgulhosos!E aos perversos: Não exalteis o vosso poder!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 75, 5, 'Não confieis em vosso poder, nem faleis com arrogância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 75, 6, 'Porque a exaltação não vem do oriente, nem do ocidente, nem do deserto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 75, 7, 'Mas sim [de] Deus, que é o Juiz; ele abate a um, e exalta a outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 75, 8, 'Porque o SENHOR [tem] um copo na mão; com vinho espumado, cheio de mistura, e ele o derramará; e os perversos da terra o beberão e sugarão até seus restos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 75, 9, 'Mas eu [o] anunciarei para sempre; cantarei louvores ao Deus de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 75, 10, 'E cortarei todas as arrogâncias dos perversos; [mas] os rostos dos justos serão exaltados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 76, 1, 'Salmo e cântico de Asafe, para o regente, com instrumentos de cordas: Deus é conhecido em Judá; grande é o seu nome em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 76, 2, 'E em Salém está seu tabernáculo, e sua morada em Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 76, 3, 'Ali ele quebrou as flechas do arco; o escudo, a espada, e a guerra. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 76, 4, 'Tu és mais ilustre [e] glorioso que montes de presas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 76, 5, 'Os ousados de coração foram despojados; dormiram seu sono; e dos homens valentes, nenhum encontrou [poder] em suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 76, 6, 'Por tua repreensão, ó Deus de Jacó, carruagens e cavalos caíram no sono [da morte] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 76, 7, 'Tu, terrível és tu; e quem subsistirá perante ti com tua ira?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 76, 8, 'Desde os céus tu anunciaste o juízo; a terra tremeu, e se aquietou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 76, 9, 'Quando Deus se levantou para o julgamento, para salvar a todos os mansos da terra. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 76, 10, 'Porque a ira humana serve para o teu louvor; com o restante da ira te cingirás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 76, 11, 'Fazei votos, e [os] pagai ao SENHOR vosso Deus; todos os que estão ao redor dele tragam presentes ao Temível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 76, 12, 'Ele cortará o espírito dos governantes; ele é temível aos reis da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 1, 'Salmo de Asafe, para o regente, conforme “Jedutum”: Clamo a Deus com minha voz, minha voz a Deus; e ele inclinará seus ouvidos a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 2, 'No dia da minha angústia busquei ao Senhor; minha mão estava continuamente estendida; minha alma não se deixava consolar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 3, 'Eu ficava me lembrando de Deus, e gemendo; ficava pensativo, e meu espírito desfalecia. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 4, 'Tu mantiveste abertas as pálpebras dos meus olhos; eu estava perturbado, e não conseguia falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 5, 'Eu ficava imaginando os dias antigos, e os anos passados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 6, 'De noite eu me lembrava de minha canção; meditava em meu coração; e meu espírito ficava procurando [entender] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 7, 'Será que o Senhor rejeitará para sempre? E nunca mais mostrará seu favor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 8, 'A sua bondade se acabou para sempre? Ele deu fim à [sua] promessa de geração em geração?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 9, 'Deus se esqueceu de ter misericórdia? Ele encerrou suas compaixões por causa de sua ira? (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 10, 'Então eu disse: Esta é a minha dor: os anos em que a mão do Altíssimo [agia] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 11, 'Eu me lembrarei das obras do SENHOR; porque me lembrarei de tuas antigas maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 12, 'Meditarei em todos as tuas obras, e falarei de teus feitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 13, 'Deus, santo [é] o teu caminho; quem é deus [tão] grande como [nosso] Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 14, 'Tu [és] o Deus que faz maravilhas; tu fizeste os povos conhecerem teu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 15, 'Com [teu] braço livraste teu povo, os filhos de Jacó e de José. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 16, 'As águas te viram, ó Deus; as águas te viram, [e] tremeram; também os abismos foram abalados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 17, 'Grandes nuvens derramaram muitas águas; os céus fizeram barulho; e também tuas flechas correram de um lado ao outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 18, 'O ruído de teus trovões [estava] nos ventos; relâmpagos iluminaram ao mundo; a terra se abalou e tremou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 19, 'Pelo mar [foi] teu caminho; e tuas veredas por muitas águas; e tuas pegadas não foram conhecidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 77, 20, 'Guiaste a teu povo como a um rebanho, pela mão de Moisés e de Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 1, 'Instrução de Asafe: Povo meu, escuta minha doutrina; inclinai vossos ouvidos às palavras de minha boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 2, 'Abrirei minha boca em parábolas; falarei mistérios dos tempos antigos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 3, 'Os quais ouvimos e conhecemos, e nossos pais nos contaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 4, 'Nós não [os] encobriremos a seus filhos, contaremos à próxima geração sobre os louvores do SENHOR, o seu poder, e suas maravilhas que ele fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 5, 'Porque ele firmou um testemunho em Jacó, e pôs a Lei em Israel, a qual ele instruiu aos nossos pais, para que eles ensinassem a seus filhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 6, 'Para que a geração seguinte [dela] soubesse; [e] os filhos que nascessem contassem a seus filhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 7, 'E [assim] pusessem sua esperança em Deus; e não se esquecessem dos feitos de Deus, mas sim, que guardassem os mandamentos dele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 8, 'E não fossem como seus pais, [que foram] uma geração teimosa e rebelde; geração que não firmou seu coração, e cujo espírito não foi fiel a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 9, 'Os filhos de Efraim, mesmo tendo arcos e flechas, viraram-se para trás no dia da batalha;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 10, 'Não guardaram o pacto de Deus, e recusaram a andar conforme sua Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 11, 'E se esqueceram de seus feitos, e de suas maravilhas que ele tinha lhes feito ver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 12, 'Ele fez maravilhas perante seus pais na terra do Egito, [no] campo de Zoã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 13, 'Ele dividiu o mar, e os fez passarem por ele; ele fez as águas ficarem paradas como [se estivessem] amontoadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 14, 'E ele os guiou com uma nuvem durante o dia, e por toda a noite com uma luz de fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 15, 'Ele partiu as rochas no deserto, e [lhes] deu de beber como que de abismos profundos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 16, 'Porque ele tirou correntes da rocha, e fez as águas descerem como rios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 17, 'E [ainda] prosseguiram em pecar contra ele, irritando ao Altíssimo no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 18, 'E tentaram a Deus nos seus corações, pedindo comida para o desejo de suas almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 19, 'E falaram contra Deus, e disseram: Poderia Deus preparar uma mesa de comida no deserto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 20, 'Eis que ele feriu a rocha, e águas correram [dela] e ribeiros fluíram em abundância; será que ele também poderia [nos] dar pão, ou preparar carne a seu povo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 21, 'Por isso o SENHOR [os] ouviu, e se irritou; e fogo se acendeu contra Jacó, e furor também subiu contra Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 22, 'Porque eles não creram em Deus, nem confiaram na salvação que dele vem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 23, 'Mesmo assim, ele deu ordens às altas nuvens, e abriu as portas dos céus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 24, 'E choveu sobre eles o maná, para comerem; e lhes deu trigo dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 25, 'Cada homem [daquele povo] comeu o pão dos anjos; ele lhes mandou comida para se fartarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 26, 'Ele fez soprar o vento do oriente nos céus, e trouxe o [vento] do sul com seu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 27, 'Ele fez chover sobre eles carne como a poeira da terra; e aves de asas como a areia do mar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 28, 'E [as] fez cair no meio de seu acampamento, ao redor de suas tendas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 29, 'Então comeram, e fartaram-se abundantemente; e satisfez o desejo deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 30, 'Porem, estando eles [ainda] não satisfeitos, enquanto a comida ainda estava em suas bocas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 31, 'a ira de Deus subiu contra eles; matou os mais robustos deles e abateu os jovens de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 32, 'Com tudo isto ainda pecaram, e não creram nas maravilhas que ele fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 33, 'Por isso gastaram seus dias em futilidades, e seus anos em terrores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 34, 'Quando ele matava [alguns dentre] eles, então buscavam por ele, e se convertiam, e buscavam a Deus de madrugada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 35, 'E se lembravam de que Deus era sua rocha, e que o Deus Altíssimo [era] o seu libertador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 36, 'Porém falavam bem dele da boca para fora, e mentiam com suas línguas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 37, 'Porque o coração deles não era comprometido para com ele, e não foram fiéis ao pacto dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 38, 'Porém ele, sendo misericordioso, perdoava a maldade deles, e não os destruía; e muitas vezes desviou de mostrar sua ira, e não despertou todo o seu furor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 39, '[Porque] se lembrou de que eles eram carne, e [como] o vento, que vai, e não volta mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 40, 'Quantas vezes o provocaram no deserto, e o maltrataram na terra desabitada!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 41, 'Pois voltavam a tentar a Deus, e perturbavam ao Santo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 42, 'Não se lembraram de sua mão, [nem] do dia em que os livrou do adversário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 43, 'Como quando ele fez seus sinais no Egito, e seus atos maravilhosos no campo de Zoã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 44, 'E transformou seus rios e suas correntes em sangue, para que não bebessem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 45, 'Enviou entre eles variedades de moscas, que os consumiu; e rãs, que os destruíram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 46, 'E deu suas colheitas ao pulgão, e o trabalho deles ao gafanhoto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 47, 'Com saraiva destruiu suas vinhas, e suas figueiras-bravas com granizo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 48, 'E entregou seu gado à saraiva; e seus animais a brasas ardentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 49, 'Mandou entre eles o ardor de sua ira: fúria, irritação e angústia, enviando mensageiros do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 50, 'Ele preparou o caminho de sua ira; não poupou suas almas da morte, e entregou seus animais à peste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 51, 'E feriu [mortalmente] a todo primogênito no Egito; as primícias nas forças nas tendas de Cam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 52, 'E levou a seu povo como a ovelhas; e os guiou pelo deserto como a um rebanho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 53, 'Ele os conduziu em segurança, e não temeram. O mar encobriu seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 54, 'E os trouxe até os limites de sua [terra] santa, até este monte, que sua mão direita adquiriu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 55, 'E expulsou as nações de diante deles, e fez com que eles repartissem as linhas de sua herança, e fez as tribos de Israel habitarem em suas tendas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 56, 'Porém eles tentaram e provocaram ao Deus Altíssimo; e não guardaram os testemunhos dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 57, 'E voltaram a ser [tão] infiéis como os seus pais; desviaram-se como um arco enganoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 58, 'E provocaram a ira dele com seus altares pagãos, e com suas imagens de escultura moveram-no de ciúmes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 59, 'Deus ouviu [isto] , e se indignou; e rejeitou gravemente a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 60, 'Por isso ele abandonou o tabernáculo em Siló, a tenda que ele havia estabelecido como habitação entre as pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 61, 'E entregou o [símbolo] de seu poder em cativeiro, e sua glória na mão do adversário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 62, 'E entregou seu povo à espada, e enfureceu-se contra sua herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 63, 'O fogo consumiu a seus rapazes, e suas virgens não tiveram músicas de casamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 64, 'Seus sacerdotes caíram à espada, e suas viúvas não lamentaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 65, 'Então o Senhor despertou como que do sono, como um homem valente que se exalta com o vinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 66, 'E feriu a seus adversários, para que recuassem, [e] lhes pôs como humilhação perpétua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 67, 'Porém ele rejeitou a tenda de José, e não escolheu a tribo de Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 68, 'Mas escolheu a tribo de Judá, o monte de Sião, a quem ele amava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 69, 'E edificou seu santuário como alturas; como a terra, a qual ele fundou para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 70, 'E ele escolheu a seu servo Davi; e o tomou dos apriscos de ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 71, 'Ele o tirou de cuidar das ovelhas geradoras de filhotes, para que ele apascentasse ao seu povo Jacó; e à sua herança Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 78, 72, 'E ele os apascentou com um coração sincero, e os guiou com as habilidades de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 1, 'Salmo de Asafe: Ó Deus, as nações invadiram a tua herança; contaminaram ao teu santo Templo; tornaram Jerusalém em amontoados de ruínas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 2, 'Deram os cadáveres dos teus servos por comida para as aves dos céus; a carne dos teus consagrados aos animais da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 3, 'Derramaram o sangue deles como água ao redor de Jerusalém, e não havia quem os enterrasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 4, 'Somos humilhados pelos nossos vizinhos; zombados e escarnecidos pelos que estão ao nosso redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 5, 'Até quando, SENHOR? Ficarás tu irado para sempre? Teus ciúmes arderão como o fogo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 6, 'Derrama o teu furor sobre as nações que não te conhecem, sobre os reinos que não clamam pelo teu nome;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 7, 'porque devoraram Jacó, e arruinaram suas habitações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 8, 'Não nos castigue pelas perversidades do passado; apressa-te, que as tuas misericórdias venham até nós, porque estamos muito fracos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 9, 'Socorre-nos, ó Deus da nossa salvação, para glorificar o teu nome; livra-nos, e perdoa os nossos pecados por causa do teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 10, 'Qual é a finalidade de que as nações digam: Onde está o Deus deles?Que a vingança do sangue derramado dos teus servos seja conhecida entre as nações, diante dos nossos olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 11, 'Chegue diante de ti o gemido dos prisioneiros; conforme o teu grande poder, salva a vida dos sentenciados à morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 12, 'E retribui a nossos vizinhos em seus corpos sete vezes tanto dos insultos que te insultaram, ó Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 79, 13, 'Assim nós, o teu povo, e as ovelhas de teu pasto, te louvaremos para sempre; de geração em geração cantaremos louvores a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 1, 'Para o regente, conforme “Susanedute”. Samo de Asafe: Ó Pastor de Israel, inclina teus ouvidos [a mim] ,tu que pastoreias a José como a ovelhas, que habitas entre os querubins, mostra teu brilho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 2, 'Perante Efraim, Benjamim e Manassés, desperta o teu poder, e vem para nos salvar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 3, 'Restaura-nos, Deus, e faz brilhar o teu rosto; e [assim] seremos salvos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 4, 'Ó SENHOR Deus dos exércitos, até quando ficarás irritado contra a oração de teu povo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 5, 'Tu os alimentas com pão de lágrimas, e lhes faz beber lágrimas com grande medida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 6, 'Puseste-nos como a briga de nossos vizinhos, e nossos inimigos zombam [de nós] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 7, 'Restaura-nos, ó Deus dos exércitos, e faz brilhar o teu rosto; e [assim] seremos salvos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 8, 'Tu transportaste [tua] vinha do Egito, tiraste as nações, e a plantaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 9, 'Preparaste [um lugar] para ela, e a fizeste estender suas raízes, e ela encheu a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 10, 'Os montes foram cobertos pela sombra dela, e seus ramos [se tornaram] como o dos mais fortes cedros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 11, 'Ela espalhou seus ramos até o mar, e seus brotos até o rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 12, 'Por que [pois] quebraste seus muros, de modo que os que passam arrancam seus frutos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 13, 'O porco do campo a destruiu; os animais selvagens a devoraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 14, 'Ó Deus dos exércitos, volta, te pedimos; olha desde os céus, e vê, e visita esta vinha;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 15, 'E a videira que tua mão direita plantou; o ramo que fortificaste para ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 16, '[Ela está] queimada pelo fogo, [e] cortada; perecem pela repreensão de tua face.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 17, 'Seja tua mão sobre o homem de tua mão direita, sobre o filho do homem a quem fortificaste para ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 18, 'Assim não desviaremos de ti; guarda-nos em vida, e chamaremos o teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 80, 19, 'SENHOR Deus dos exércitos, restaura-nos; faz brilhar o teu rosto, e [assim] seremos salvos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 1, 'Salmo de Asafe, para o regente, conforme “Gitite”: Cantai de alegria a Deus, [que é] nossa força; mostrai alegria ao Deus de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 2, 'Levantai uma canção, e dai-nos o tamborim; a agradável harpa com a lira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 3, 'Tocai trombeta na lua nova; e na lua cheia, no dia de nossa celebração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 4, 'Porque [isto] é um estatuto em Israel, e uma ordem do Deus de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 5, 'Ele o pôs como testemunho em José, quando tinha saído contra a terra do Egito, [onde] ouvi uma língua que eu não entendia:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 6, 'Tirei seus ombros de debaixo da carga; suas mãos foram livrados dos cestos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 7, 'Na angústia clamaste, e livrei-te dela; te respondi no esconderijo dos trovões; provei a ti nas águas de Meribá. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 8, 'Ouve [-me] , povo meu, e eu te darei testemunho; ó Israel, se tu me ouvisses!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 9, 'Não haverá entre ti deus estranho, e não te prostrarás a um deus estrangeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 10, 'Eu sou o SENHOR teu Deus, que te fiz subir da terra do Egito; abre tua boca por completo, e eu a encherei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 11, 'Mas meu povo não ouviu minha voz, e Israel não me quis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 12, 'Por isso eu os entreguei ao desejo de seus próprios corações, e andaram conforme seus próprios conselhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 13, 'Ah, se meu povo me ouvisse, se Israel andasse em meus caminhos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 14, 'Em pouco tempo eu derrotaria seus inimigos, e viraria minha mão contra seus adversários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 15, 'Os que odeiam ao SENHOR, a ele se submeteriam, e o tempo [da punição] deles seria eterno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 81, 16, 'E ele sustentaria [Israel] com a abundância de trigo; e eu te fartaria com o mel da rocha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 82, 1, 'Salmo de Asafe: Deus está na congregação dos poderosos, e julga no meio dos deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 82, 2, 'Até quando julgareis injustamente, e favoreceis a aparência dos perversos? (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 82, 3, 'Fazei justiça ao pobre e ao órfão; defendei o afligido e o pobre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 82, 4, 'Livrai ao pobre e necessitado, resgatai [-o] das mãos dos perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 82, 5, 'Eles nada conhecem, nem entendem; continuamente andam em trevas; abalam-se todos os fundamentos da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 82, 6, 'Eu disse: Sois deuses; e todos vós sois filhos do Altíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 82, 7, 'Porém morrereis como homens, e caireis como qualquer um dos líderes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 82, 8, 'Levanta-te, ó Deus; julga a terra, pois tu és o dono de todas as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 1, 'Cântico e Salmo de Asafe: Deus, não fiques em silêncio; não estejas indiferente, nem fiques quieto, ó Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 2, 'Porque eis que teus inimigos fazem barulho, e aqueles que te odeiam levantam a cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 3, 'Planejam astutos conselhos contra teu povo, e se reúnem para tramar contra teus preciosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 4, 'Eles disseram: Vinde, e os destruamos, para que não sejam mais um povo, e nunca mais seja lembrado o nome de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 5, 'Porque tomaram conselhos com uma só intenção; fizeram aliança contra ti:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 6, 'As tendas de Edom, e dos ismaelitas, de Moabe, e dos agarenos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 7, 'De Gebal, e de Amom, e de Amaleque; dos filisteus, com os moradores de Tiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 8, 'A Assíria também se aliou a eles; eles foram a força dos filhos de Ló. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 9, 'Faze a eles como a Midiã, como a Sísera, como a Jabim no ribeiro de Quisom,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 10, '[Que] pereceram em Endor; vieram a ser esterco da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 11, 'Faze a eles [e] a seus nobres como a Orebe, e como Zeebe; e a todos os seus príncipes como a Zebá, e como a Zalmuna,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 12, 'Que disseram: Tomemos posse para nós dos terrenos de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 13, 'Deus meu, faze-os como a um redemoinho, como a palhas perante o vento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 14, 'Como o fogo, que queima uma floresta, e como a labareda que incendeia as montanhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 15, 'Persegue-os assim com tua tempestade, e assombra-os com o teu forte vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 16, 'Enche os rostos deles de vergonha, para que busquem o teu nome, SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 17, 'Sejam envergonhados e assombrados para sempre, e sejam humilhados, e pereçam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 83, 18, 'Para que saibam que tu, (e teu nome é EU-SOU), és o Altíssimo sobre toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 84, 1, 'Para o regente, com “Gitite”. Salmo dos filhos de Coré: Quão agradáveis são tuas moradas, SENHOR dos exércitos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 84, 2, 'Minha alma está desejosa, ao ponto de desmaiar, pelos pátios do SENHOR; meu coração e minha carne clamam ao Deus vivente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 84, 3, 'Até o pardal acha casa, e a andorinha ninho para si, onde ponha filhotes perto de teus altares, ó SENHOR dos exércitos, Rei meu e Deus meu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 84, 4, 'Bem-aventurados os que habitam em tua casa; eles louvam a ti continuamente. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 84, 5, 'Bem-aventurados aqueles cuja força está em ti, em cujos corações estão os caminhos [corretos] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 84, 6, 'Eles, ao passarem pelo Vale de Baca, fazem dele uma fonte; e a chuva o cobre de bênçãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 84, 7, 'Eles vão de força em força; [cada um deles] comparece diante de Deus em Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 84, 8, 'SENHOR Deus dos exércitos, escuta minha oração; inclina os teus ouvidos, ó Deus de Jacó. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 84, 9, 'Olha o nosso escudo, ó Deus; e observa o rosto do teu ungido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 84, 10, 'Porque melhor é um dia nos teus pátios, do que mil [fora] . Prefiro estar à porta da casa do meu Deus, a morar nas tendas dos perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 84, 11, 'Porque o SENHOR Deus é sol e escudo; o SENHOR concederá graça e honra; ele não negará o bem aos que andam em integridade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 84, 12, 'Ó SENHOR dos exércitos, bem-aventurado é o homem que confia em ti!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 1, 'Salmo para o regente, dos filhos de Coré: Foste favorável, ó SENHOR, à tua terra; restauraste Jacó de seu infortúnio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 2, 'Perdoaste a perversidade de teu povo; encobriste todos os seus pecados. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 3, 'Removeste toda a tua indignação; do ardor de tua ira te desviaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 4, 'Restaura-nos, ó Deus de nossa salvação; e cessa tua ira de sobre nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 5, 'Acaso estarás irado contra nós para sempre? Estenderás a tua ira de geração em geração?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 6, 'Não voltará a dar-nos vida, para que o teu povo se alegre em ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 7, 'Mostra-nos tua bondade, SENHOR, e dá para nós tua salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 8, 'Escutarei o que o Deus, o SENHOR, falar, pois ele falará de paz ao seu povo, e aos seus santos, contanto que não voltem à loucura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 9, 'Certamente sua salvação está perto daqueles que o temem, para que a glória habite em nossa terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 10, 'A bondade e a verdade se encontrarão; a justiça e a paz se beijarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 11, 'A verdade brotará da terra, e a justiça olhará desde os céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 12, 'E o SENHOR também dará o bem; e a nossa terra dará o seu fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 85, 13, 'A justiça irá adiante dele, e ele nos porá no caminho de seus passos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 1, 'Oração de Davi: Inclina teus ouvidos, SENHOR, e ouve-me, porque estou aflito e necessitado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 2, 'Guarda minha alma, porque eu sou dedicado [a ti] ; ó Deus, salva o teu servo, que confia em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 3, 'Tem misericórdia de mim, SENHOR, porque clamo a ti o dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 4, 'Alegra a alma de teu servo; porque a ti, Senhor, levanto a minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 5, 'Pois tu, Senhor, és bom, perdoador, e grande em bondade para todos os que clamam a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 6, 'Inclina, SENHOR, teus ouvidos à minha oração; e presta atenção à voz de minhas súplicas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 7, 'No dia de minha angústia clamarei a ti, pois tu me responderás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 8, 'Não há semelhante a ti entre os deuses, ó Senhor; e nem obras como as tuas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 9, 'Todas as nações que tu fizeste virão e se prostrarão diante de ti, Senhor; e elas glorificarão o teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 10, 'Pois tu és grande, e fazes maravilhas; somente tu és Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 11, 'Ensina-me, SENHOR, o teu caminho, [e] eu andarei em tua verdade; une meu coração com o temor ao teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 12, 'Louvarei a ti, ó Senhor meu Deus, com todo o meu coração; e glorificarei o teu nome para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 13, 'Pois grande é a tua misericórdia para comigo; e livraste minha alma das profundezas do Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 14, 'Ó Deus, pessoas arrogantes têm se levantado contra mim; e muitos violentos procuram [matar] a minha alma, e te desprezam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 15, 'Porém tu, Senhor, és Deus misericordioso e piedoso; tardio para se irar, e abundante em bondade e verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 16, 'Volta-te para mim, e tem piedade de mim; dá tua força a teu servo, e salva o filho de tua serva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 86, 17, 'Faze-me um sinal de bondade, para que os que me odeiam vejam, e se envergonhem; porque tu, SENHOR, tens me ajudado e consolado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 87, 1, 'Salmo e cântico, dos filhos de Coré: Seu fundamento está nos santos montes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 87, 2, 'O SENHOR ama os portões de Sião mais que todas as habitações de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 87, 3, 'Gloriosas coisas são faladas de ti, ó cidade de Deus. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 87, 4, 'Farei menção de Raabe e Babilônia aos que me conhecem; eis que da Filístia, Tiro e Cuxe [se dirá] : Este é nascido ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 87, 5, 'E de Sião se dirá: Este e aquele outro nasceram ali. E o próprio Altíssimo a manterá firme.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 87, 6, 'O SENHOR contará, quando escrever dos povos: Este nasceu ali. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 87, 7, 'Assim como os cantores e instrumentistas; todas as minhas fontes estão em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 1, 'Cântico e Salmo dos filhos de Coré, para o regente, conforme “Maalate Leanote”. Instrução feita por Hemã, o Ezraíta: Ó SENHOR Deus de minha salvação, dia [e] noite clamo diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 2, 'Que minha oração chegue à tua presença; inclina os teus ouvidos ao meu clamor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 3, 'Porque minha alma está cheia de aflições, e minha vida se aproxima do Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 4, 'Já estou contado entre os que descem à cova; tornei-me um homem sem forças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 5, 'Abandonado entre os mortos, como os feridos de morte que jazem na sepultura, aos quais tu já não te lembra mais, e já estão cortados [para fora do poder] de tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 6, 'Puseste-me na cova mais profunda, nas trevas [e] nas profundezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 7, 'O teu furor pesa sobre mim, e [me] oprimiste com todas as tuas ondas. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 8, 'Afastaste de mim os meus conhecidos, fizeste-me abominável para com eles; estou preso, e não posso sair.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 9, 'Meus olhos estão fracos por causa da opressão; clamo a ti, SENHOR, o dia todo; a ti estendo minhas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 10, 'Farás tu milagres aos mortos? Ou mortos se levantarão, e louvarão a ti? (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 11, 'Tua bondade será contada na sepultura? Tua fidelidade na perdição?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 12, 'Serão conhecidas tuas maravilhas nas trevas? E tua justiça na terra do esquecimento?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 13, 'Porém eu, SENHOR, clamo a ti; e minha oração vem ao teu encontro de madrugada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 14, 'Por que tu, SENHOR, rejeitas minha alma, e escondes tua face de mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 15, 'Tenho sido afligido e estou perto da morte desde a minha juventude; tenho sofrido teus temores, e estou desesperado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 16, 'Os ardores de tua ira têm passado por mim; teus terrores me destroem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 17, 'Rodeiam-me como águas o dia todo; cercam-me juntos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 88, 18, 'Afastaste de mim meu amigo e meu companheiro; meus conhecidos [estão em] trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 1, 'Instrução de Etã Ezraíta: Cantarei das bondades do SENHOR para sempre; de geração em geração com minha boca anunciarei tua fidelidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 2, 'Porque eu disse: [Tua] bondade durará para sempre; confirmaste tua fidelidade até nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 3, '[Tu disseste] : Eu fiz um pacto com o meu escolhido, jurei a meu servo Davi. [Eu lhe disse] :'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 4, 'Confirmarei tua semente para sempre, e farei teu trono continuar de geração em geração. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 5, 'Que os céus louvem as tuas maravilhas, SENHOR; pois tua fidelidade [está] na congregação dos santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 6, 'Porque quem no céu pode se comparar ao SENHOR? E quem é semelhante ao SENHOR entre os filhos dos poderosos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 7, 'Deus é terrível na assembleia dos santos, e mais temível do que todos os que estão ao seu redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 8, 'Ó SENHOR Deus dos exércitos, quem é poderoso como tu, SENHOR? E tua fidelidade está ao redor de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 9, 'Tu dominas a arrogância do mar; quando suas ondas se levantam, tu as aquietas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 10, 'Quebraste a Raabe como que ferida de morte; com teu braço forte espalhaste os teus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 11, 'Teus são os céus, também tua é a terra; o mundo e sua plenitude, tu os fundaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 12, 'O norte e o sul, tu os criaste; Tabor e Hermon têm muita alegria em teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 13, 'Tu tens um braço poderoso; forte é tua mão, [e] alta está tua mão direita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 14, 'Justiça e juízo são a base de teu trono; bondade e verdade vão adiante de teu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 15, 'Bem-aventurado é o povo que entende o grito de alegria; ó SENHOR, eles andarão na luz de tua face.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 16, 'Em teu nome se alegrarão o dia todo, e em tua justiça serão exaltados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 17, 'Porque tu és a glória de sua força, e por tua boa vontade nosso poder é exaltado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 18, 'Porque ao SENHOR pertence nosso escudo; e o Santo de Israel é nosso Rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 19, 'Então em visão falaste ao teu santo, e disseste: Pus o socorro sobre um valente; exaltei a um escolhido dentre o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 20, 'Achei a Davi, meu servo; eu o ungi com meu óleo santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 21, 'Com ele minha mão será firme; e também meu braço o fortalecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 22, 'O inimigo não tomará suas riquezas, nem o filho da perversidade o afligirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 23, 'Porém eu espancarei seus adversários, e ferirei aos que o odeiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 24, 'E minha fidelidade e minha bondade serão com ele; e em meu nome seu poder será exaltado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 25, 'Porei a mão dele no mar, e sua mão direita nos rios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 26, 'Ele me chamará: Tu és meu Pai, meu Deus, e a rocha da minha salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 27, 'Eu também o porei como primogênito, mais alto que todos os reis da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 28, 'Manterei minha bondade para com ele para sempre, e meu pacto com ele será firme.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 29, 'Conservarei sua semente para sempre, e o trono dele como os dias dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 30, 'Se seus filhos deixarem minha Lei, e não andarem em meus juízos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 31, 'Se profanarem os meus estatutos, e não guardarem os meus mandamentos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 32, 'Então punirei a transgressão deles com vara, e a perversidade deles com açoite,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 33, 'Porém nunca tirarei minha bondade dele, nem falharei em minha fidelidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 34, 'Não quebrarei o meu pacto, e o que saiu dos meus lábios não mudarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 35, 'Uma vez jurei por minha Santidade, [e] nunca mentirei a Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 36, 'A semente dele durará para sempre, e o trono dele [será] como o sol perante mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 37, 'Assim como a lua, ele será confirmado para sempre; e a testemunha no céu é fiel. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 38, 'Porém tu te rebelaste, e [o] rejeitaste; ficaste irado contra o teu Ungido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 39, 'Anulaste o pacto do teu servo; desonraste a coroa dele [lançando-a] contra a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 40, 'Derrubaste todos os seus muros; quebraste suas fortificações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 41, 'Todos os que passam pelo caminho o despojaram; ele foi humilhado por seus vizinhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 42, 'Levantaste a mão direita de seus adversários; alegraste a todos os inimigos dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 43, 'Também deixaste de afiar sua espada; e não o sustentaste na batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 44, 'Fizeste cessar sua formosura; e derrubaste seu trono à terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 45, 'Encurtaste os dias de sua cidade; cobriste-o de vergonha. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 46, 'Até quando, SENHOR? Tu te esconderás para sempre? Arderá teu furor como o fogo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 47, 'Lembra-te de que curta é minha vida; por que criarias em vão todos os filhos dos homens?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 48, 'Que homem vive, que não experimente a morte? Livrará ele a sua alma do poder do Xeol? (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 49, 'Senhor, onde estão as tuas bondades do passado, que juraste a Davi por tua fidelidade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 50, 'Lembra-te, Senhor, da humilhação de teus servos, que eu trago em meu peito, [causada] por todos e grandes povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 51, 'Com [humilhação] os teus inimigos insultam, SENHOR, com a qual insultam os passos do teu ungido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 89, 52, 'Bendito [seja] o SENHOR para todo o sempre. Amém, e Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 1, 'Oração de Moisés, homem de Deus: Senhor, tu tens sido nossa habitação, de geração em geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 2, 'Antes que os montes surgissem, e tu produzisses a terra e o mundo, desde à eternidade até a eternidade tu és Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 3, 'Tu fazes o homem voltar ao pó, e dizes: Retornai-vos, filhos dos homens!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 4, 'Porque mil anos aos teus olhos são como o dia de ontem, que passou, e como a vigília da noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 5, 'Tu os levas como correntes de águas; são como o sono; de madrugada são como a erva que brota:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 6, 'De madrugada floresce, e brota; à tarde é cortada, e se seca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 7, 'Porque perecemos com tua ira, e nos assombramos com teu furor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 8, 'Tu pões nossas perversidades perante ti, nosso [pecado] oculto [perante] a luz do teu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 9, 'Porque todos os nossos dias se vão por causa de tua irritação; acabamos nossos anos como um suspiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 10, 'Os dias de nossa vida [chegam até] os setenta anos; e os que são mais fortes, até os oitenta anos; e o melhor deles é canseira e opressão, porque logo é cortado, e saímos voando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 11, 'Quem conhece a força de tua ira? O teu furor é conforme o temor a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 12, 'Ensina [-nos] a contar nossos dias de tal maneira que alcancemos um coração sábio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 13, 'Retorna, SENHOR! Até quando? [Tem] compaixão para com teus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 14, 'Farta-nos de manhã com tua bondade; e nos alegraremos e seremos cheios de alegria por todos os nossos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 15, 'Alegra-nos conforme os dias [em que] tu nos afligiste, os anos [em que] vimos o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 16, 'Que tua obra apareça aos teus servos, e tua glória sobre seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 90, 17, 'E que o agrado do SENHOR nosso Deus seja sobre nós; e confirma as obras de nossas mãos sobre nós; sim, a obra de nossas mãos, confirma!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 1, 'Aquele que mora no esconderijo do Altíssimo, à sombra do Todo-Poderoso habitará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 2, 'Direi ao SENHOR: [Tu és] meu refúgio e minha fortaleza; Deus meu, em quem confio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 3, 'Porque ele te livrará do laço do caçador e da peste maligna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 4, 'Com suas penas ele te cobrirá, e debaixo de suas asas estarás protegido; a verdade dele é escudo grande e protetor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 5, 'Não terás medo do terror da noite, [nem] da flecha que voa de dia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 6, '[Nem] da peste que anda às escuras, [nem] da mortandade que assola ao meio-dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 7, 'Cairão mil ao teu lado, e dez mil à tua direita, [mas] a ti nada alcançará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 8, 'Somente verás com teus olhos, e observarás o pagamento dos perversos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 9, 'Porque tu fizeste como morada ao SENHOR: o meu refúgio, o Altíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 10, 'Mal nenhum te sucederá, nem praga alguma chegará à tua tenda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 11, 'Porque ele ordenou aos anjos quanto a ti, para que guardem todos os teus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 12, 'Pelas mãos te levarão, para que não tropeces teu pé em alguma pedra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 13, 'Tu pisarás sobre o leão e a cobra; passarás esmagando ao filho do leão e à serpente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 14, 'Por ele ter me amado tanto, eu também o livrarei; em alto retiro eu o porei, porque ele conhece o meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 15, 'Ele me chamará, e eu o responderei; estarei com ele na angústia; [dela] eu o livrarei, e o honrarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 91, 16, 'Eu o satisfarei com uma longa vida , e lhe mostrarei a minha salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 1, 'Salmo e cântico para o dia do Sábado: Bom é louvar ao SENHOR, e cantar louvores ao teu nome, ó Altíssimo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 2, 'Para anunciar tua bondade pela manhã, e tua fidelidade durante as noites.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 3, 'Com o instrumento de dez cordas, com a lira, e com música de harpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 4, 'Porque tu, SENHOR, tens me alegrado com teus feitos; cantarei de alegria pelas obras de tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 5, 'Ó SENHOR, como são grandes tuas obras! Muito profundos são teus pensamentos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 6, 'O homem bruto não os conhece, nem o tolo entende isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 7, 'Quando os perversos crescem como a erva, e florescem todos os praticantes de maldade, [assim então] serão destruídos para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 8, 'Mas tu és Altíssimo para sempre, SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 9, 'Porque eis que teus inimigos, SENHOR, porque eis que teus inimigos pereceram; serão dispersos todos os praticantes de maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 10, 'Porém tu exaltaste o meu poder, como que um chifre de touro selvagem; eu fui ungido com óleo fresco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 11, 'E meus olhos verão [o fim] dos meus inimigos; meus ouvidos ouvirão [o fim] dos malfeitores que se levantam contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 12, 'O justo florescerá como a palma; crescerá como o cedro do Líbano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 13, 'Os [justos] estão plantados na casa do SENHOR, crescerão nos pátios do nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 14, '[Até] na velhice ainda darão fruto; serão fortes e verdes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 92, 15, 'Para anunciarem que o SENHOR é correto; ele é minha rocha, e não há perversidade nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 93, 1, 'O SENHOR reina. Ele está vestido de majestade; o SENHOR está vestido de poder, [com o qual] se envolveu. O mundo está firmado, não se abalará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 93, 2, 'Teu trono está firme desde o passado; tu [és] desde a eternidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 93, 3, 'SENHOR, os rios levantam; os rios levantam seus ruídos; os rios levantam suas ondas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 93, 4, '[Porém] o SENHOR nas alturas é mais forte que os ruídos de muitas águas, [mais que] as fortes ondas do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 93, 5, 'Muito fiéis são teus testemunhos; a santidade embeleza tua casa, SENHOR, para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 1, 'Ó Deus das vinganças, SENHOR Deus das vinganças, mostra-te com teu brilho!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 2, 'Exalta-te, ó Juiz da terra! Retribui com punição aos arrogantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 3, 'Até quando os perversos, SENHOR, até quando os perversos se alegrarão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 4, 'Eles falam [demais] , e dizem palavras soberbas; todos os que praticam a maldade se orgulham.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 5, 'Eles despedaçam ao teu povo, SENHOR, e humilham a tua herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 6, 'Eles matam a viúva e o estrangeiro, e tiram a vida dos órfãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 7, 'E dizem: O SENHOR não vê [isso] , e o Deus de Jacó não está prestando atenção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 8, 'Entendei, ó tolos dentre o povo; e vós [que sois] loucos, quando sereis sábios?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 9, 'Por acaso aquele que criou os ouvidos não ouviria? Aquele que formou os olhos não veria?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 10, 'Aquele que disciplina as nações não castigaria? É ele o que ensina o conhecimento ao homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 11, 'O SENHOR conhece os pensamentos do homem, que são inúteis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 12, 'Bem-aventurado é o homem a quem tu disciplinas, SENHOR, e em tua Lei o ensinas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 13, 'Para tu lhe dares descanso dos dias de aflição, até que seja cavada a cova para o perverso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 14, 'Pois o SENHOR não abandonará o seu povo, nem desamparará a sua herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 15, 'Porque o juízo restaurará a justiça, e todos os corretos de coração o seguirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 16, 'Quem se levantará em meu favor contra os malfeitores? Quem se porá em meu favor contra os praticantes de perversidade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 17, 'Se o SENHOR não tivesse sido meu socorro, minha alma logo teria vindo a morar no silêncio [da morte] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 18, 'Quando eu dizia: Meu pé está escorregando;Tua bondade, ó SENHOR, me sustentava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 19, 'Quando minhas preocupações se multiplicavam dentro de mim, teus consolos confortaram a minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 20, 'Por acaso teria comunhão contigo o trono da maldade, que faz leis opressivas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 21, 'Muitos se juntam contra a alma do justo, e condenam o sangue inocente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 22, 'Mas o SENHOR é meu alto retiro, e meu Deus a rocha de meu refúgio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 94, 23, 'E ele fará voltar sobre eles suas próprias perversidades, e por suas maldades ele os destruirá; o SENHOR nosso Deus os destruirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 95, 1, 'Vinde, cantemos alegres ao SENHOR; gritemos [de alegria] à rocha de nossa salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 95, 2, 'Cheguemos adiante de sua presença com agradecimentos; cantemos salmos a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 95, 3, 'Porque o Senhor é o grande Deus, e maior Rei do que todos os deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 95, 4, 'Na mão dele estão as profundezas da terra; e a ele pertencem os altos montes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 95, 5, 'Dele [também] é o mar, pois ele o fez; e suas mãos formaram a [terra] seca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 95, 6, 'Vinde, adoremos, e prostremo-nos; ajoelhemo-nos perante o SENHOR, que nos fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 95, 7, 'Porque ele é o nosso Deus, e nós [somos] o povo do seu pasto, e as ovelhas de sua mão. Se hoje ouvirdes a voz dele,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 95, 8, 'Não endureçais vosso coração, como em Meribá, como no dia da tentação no deserto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 95, 9, 'Onde vossos pais me tentaram; eles me provaram, mesmo já tendo visto minha obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 95, 10, 'Por quarenta anos aguentei com desgosto d [esta] geração, e disse: Este povo se desvia em seus corações; e eles não conhecem meus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 95, 11, 'Por isso jurei em minha ira que eles não entrarão no meu [lugar] de descanso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 1, 'Cantai ao SENHOR uma nova canção; cantai ao SENHOR toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 2, 'Cantai ao SENHOR, bendizei ao seu nome; anunciai todos os dias sua salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 3, 'Contai sua glória por entre as nações, [e] suas maravilhas por entre todos os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 4, 'Porque o SENHOR é grande e muito digno de louvor; ele é mais temível que todos os deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 5, 'Porque todos os deuses dos povos são ídolos, porém o SENHOR fez os céus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 6, 'Majestade e glória há diante dele; força e beleza [há] em seu santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 7, 'Reconhecei ao SENHOR, ó famílias dos povos; reconhecei que ao SENHOR pertence a glória e a força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 8, 'Reconhecei ao SENHOR a glória de seu nome; trazei ofertas, e entrai nos pátios dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 9, 'Adorai ao SENHOR na glória da santidade; temei perante sua presença toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 10, 'Dizei entre as nações: O SENHOR reina; o mundo está firme, e não se abalará; ele julgará aos povos de forma correta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 11, 'Alegrem-se os céus, e enchei de alegria a terra; faça barulho o mar e sua plenitude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 12, 'Saltem contentes o campo e tudo que nele há, e que todas as árvores dos bosque cantem de alegria,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 96, 13, 'Diante do SENHOR; porque ele vem; porque ele vem para julgar a terra. Ele julgará ao mundo com justiça, e aos povos com sua verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 97, 1, 'O SENHOR reina; que a terra se encha de alegria; alegrem-se as muitas ilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 97, 2, 'Nuvens e escuridão há ao redor dele; justiça e juízo são a base de seu trono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 97, 3, 'Fogo vai adiante dele, que inflama seus adversários ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 97, 4, 'Seus relâmpagos iluminam o mundo; a terra os vê, e treme.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 97, 5, 'Os montes se derretem como cera na presença do SENHOR, na presença do Senhor de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 97, 6, 'Os céus anunciam sua justiça, e todos os povos veem sua glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 97, 7, 'Sejam envergonhados todos os que servem a imagens, e os que se orgulham de ídolos; prostrai-vos diante dele todos os deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 97, 8, 'Sião ouviu, e se alegrou; e as filhas de Judá tiveram muita alegria, por causa de teus juízos, SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 97, 9, 'Pois tu, SENHOR, és o Altíssimo sobre toda a terra; tu és muito mais elevado que todos os deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 97, 10, 'Vós que amais ao SENHOR: odiai o mal; ele guarda a alma de seus santos, [e] os resgata da mão dos perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 97, 11, 'A luz é semeada para o justo, e a alegria para os corretos de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 97, 12, 'Vós justos, alegrai-vos no SENHOR; e agradecei em memória de sua santidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 98, 1, 'Salmo: Cantai ao SENHOR uma canção nova, porque ele fez maravilhas; sua mão direita e seu santo braço lhe fez ter a salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 98, 2, 'O SENHOR fez ser conhecida sua salvação; perante os olhos das nações ele mostrou sua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 98, 3, 'Ele se lembrou de sua bondade e de sua fidelidade para com a casa de Israel; todos os confins da terra viram a salvação de nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 98, 4, 'Gritai de alegria ao SENHOR, toda a terra; clamai, cantai alegres, e tocai salmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 98, 5, 'Tocai ao SENHOR com harpa; com harpa, e com a voz da música;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 98, 6, 'Com trombetas, e som de cornetas, clamai alegremente diante do Rei SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 98, 7, 'Faça barulho o mar com sua plenitude; o mundo com os que nele habitam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 98, 8, 'Que os rios batam palmas, que as montanhas juntamente se alegrem,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 98, 9, 'Diante do SENHOR, porque ele vem para julgar a terra; ele julgará ao mundo com justiça, e aos povos de forma correta.')
